const body = $('Webhook').first().json.body || {};

let tagUuidList = [];
if (body.tag_name_uuid) {
  if (Array.isArray(body.tag_name_uuid)) {
    tagUuidList = body.tag_name_uuid;
  } else if (typeof body.tag_name_uuid === 'string') {
    try {
      const parsed = JSON.parse(body.tag_name_uuid);
      tagUuidList = Array.isArray(parsed) ? parsed : [body.tag_name_uuid];
    } catch (e) {
      tagUuidList = body.tag_name_uuid.split(',').map(s => s.trim()).filter(Boolean);
    }
  }
}

let orgIdList = [];
if (body.org_id) {
  if (Array.isArray(body.org_id)) {
    orgIdList = body.org_id;
  } else if (typeof body.org_id === 'string') {
    try {
      const parsed = JSON.parse(body.org_id);
      orgIdList = Array.isArray(parsed) ? parsed : [body.org_id];
    } catch (e) {
      orgIdList = body.org_id.split(',').map(s => s.trim()).filter(Boolean);
    }
  }
}

let questionsList = [];
if (body.questions) {
  if (Array.isArray(body.questions)) {
    questionsList = body.questions;
  } else if (typeof body.questions === 'string') {
    try {
      const parsed = JSON.parse(body.questions);
      if (Array.isArray(parsed)) questionsList = parsed;
    } catch (e) {}
  }
}

const normalizedQuestions = questionsList.map(q => {
  const num = q["number of question"] !== undefined ? q["number of question"] : (q["number_of_questions"] !== undefined ? q["number_of_questions"] : (q["count"] || 1));
  const rawLevel = String(q.level || "normal").trim().toLowerCase();
  const levelMap = {
    'theory_application': 'review_exercise',
    'review_exercise': 'review_exercise',
    'basic': 'basic',
    'medium': 'normal',
    'normal': 'normal',
    'advanced': 'advance',
    'advance': 'advance',
    'exploration': 'discovery',
    'discovery': 'discovery'
  };
  const normalizedLevel = levelMap[rawLevel] || rawLevel;
  return {
    title: q.title || "Bài tập tổng hợp",
    level: normalizedLevel,
    type: q.type || "multiple_choice",
    number_of_questions: parseInt(num, 10) || 1
  };
});

let criteriaObj = body.criteria || {};
if (typeof criteriaObj === 'string') {
  try {
    criteriaObj = JSON.parse(criteriaObj);
  } catch(e) {
    criteriaObj = { "tiêu chí": body.criteria };
  }
}

return {
  body: {
    tag_name_uuid: tagUuidList,
    org_id: orgIdList,
    questions: normalizedQuestions,
    criteria: criteriaObj,
    user_id: body.user_id || "system",
    conversation_id: body.conversation_id || null
  }
};

const securityNode = $('Security & Sanitization Gate').first().json.body || {};
const tagUuids = securityNode.tag_name_uuid || [];
const orgIds = securityNode.org_id || [];
const questions = securityNode.questions || [];
const userId = securityNode.user_id || "system";
const conversationId = securityNode.conversation_id || null;

let outlineTopics = [];
let outlineStr = "";
let isOutOfScope = false;

if (tagUuids.length > 0 || orgIds.length > 0) {
  try {
    const outlineData = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:8080/api/outline',
      body: {
        tag_name_uuids: tagUuids,
        org_ids: orgIds,
        doc_type: "doc"
      },
      json: true
    });

    if (outlineData && outlineData.outline) {
      const files = Object.keys(outlineData.outline);
      files.forEach(f => {
        const lessons = outlineData.outline[f] || [];
        lessons.forEach(l => {
          if (l.lesson_name) outlineTopics.push(l.lesson_name.toLowerCase());
        });
      });
      if (outlineTopics.length > 0) {
        outlineStr = "Các chủ đề có trong tài liệu SGK:\n- " + Array.from(new Set(outlineTopics)).join("\n- ");
      }
    }
  } catch(e) {}
}

const requestedTitles = questions.map(q => q.title).filter(Boolean);
const queryText = requestedTitles.join(" ") || "bài tập toán tiểu học";

if (outlineTopics.length > 0 && requestedTitles.length > 0) {
  const allTopicsCombined = outlineTopics.join(" ");
  let matchedCount = 0;
  for (const title of requestedTitles) {
    const titleTokens = title.toLowerCase().split(/\s+/).filter(t => t.length > 2);
    const hasMatch = titleTokens.some(t => allTopicsCombined.includes(t));
    if (hasMatch) matchedCount++;
  }
  if (matchedCount === 0) {
    isOutOfScope = true;
  }
}

let contextTexts = [];
let citations = [];
let citationList = [];
let retrievalFailed = false;

if (!isOutOfScope) {
  try {
    const retrievalRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:8080/api/retrieval',
      body: {
        text: queryText,
        tag_name_uuids: tagUuids,
        org_ids: orgIds,
        type: "doc",
        top_k: 5,
        user_id: userId,
        conversation_id: conversationId
      },
      json: true
    });

    const results = (retrievalRes.results || []).filter(r => r.distance === undefined || r.distance < 1.3);
    if (results.length === 0) {
      retrievalFailed = true;
    } else {
      results.forEach((chunk, index) => {
        const meta = chunk.metadata || {};
        const physPage = meta.physical_page;
        const pdfPage = meta.pdf_page_number || (meta.pdf_page_index !== undefined ? meta.pdf_page_index + 1 : undefined);
        const pageStr = (physPage !== undefined && physPage !== -1) ? `Trang ${physPage}` : (pdfPage !== undefined ? `Trang PDF ${pdfPage}` : 'Trang chưa rõ');
        const lessonName = meta.lesson_name || 'Chưa rõ';
        const fileName = meta.file_name || 'SGK Toán 3';
        const volume = meta.volume || '1';
        contextTexts.push(`--- Đoạn ${index + 1}: ${fileName}, ${pageStr} ---\n${chunk.text}`);
        citations.push(`- **Tài liệu:** ${fileName} | **Bài học:** ${lessonName} | **Vị trí:** ${pageStr} (Tập ${volume})`);
        citationList.push({ document: fileName, lesson: lessonName, position: pageStr, volume: String(volume) });
      });
    }
  } catch(e) {
    retrievalFailed = true;
  }
}

if (isOutOfScope || retrievalFailed) {
  isOutOfScope = true;
}

return {
  out_of_scope: isOutOfScope,
  joined_context: contextTexts.join('\n\n'),
  citation_block: citations.join('\n'),
  citation_list: citationList,
  outline_str: outlineStr,
  questions: questions,
  criteria: securityNode.criteria,
  user_id: userId,
  conversation_id: conversationId
};

const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || "";
const msg = "Không có thông tin để trả lời";

return {
  status: "out_of_scope",
  agent: "out_of_scope",
  type: "text",
  conversation_id: conversationId,
  output: msg,
  message: msg
};

const item = $json;
const questions = item.questions || [];
const criteria = item.criteria || {};
const joinedContext = item.joined_context || "";
const userId = item.user_id || "system";
const conversationId = item.conversation_id || null;

const systemInstruction = `[SYSTEM INSTRUCTION - CUSTOM EXERCISE GENERATOR AGENT]
Bạn là Chuyên gia Biên soạn Bài tập Toán Sư phạm Tiểu học. Nhiệm vụ của bạn là dựa vào Ngữ cảnh tài liệu Sách Giáo Khoa (SGK) được cung cấp để tạo ra bộ bài tập toán chất lượng cao, đúng theo các yêu cầu chi tiết của người dùng.

1. QUY ĐỊNH ĐỘ KHÓ (LEVEL):
- "review_exercise" (tương đương "theory_application"): Bài tập ôn lại kiến thức vừa học, củng cố các định nghĩa, quy tắc và công thức cốt lõi vừa học trong bài.
- "basic": Mức độ nhận biết, câu hỏi cơ bản, trực tiếp, kiểm tra khả năng ghi nhớ và nhận biết khái niệm cơ bản.
- "normal" (tương đương "medium"): Mức độ thông hiểu, áp dụng trực tiếp các quy tắc, công thức để giải bài toán tiêu chuẩn 1-2 bước.
- "advance" (tương đương "advanced"): Mức độ vận dụng cao, nâng cao, yêu cầu tư duy phân tích, tổng hợp, bài toán nhiều bước giải.
- "discovery" (tương đương "exploration"): Câu hỏi khám phá liên quan đến đời sống thực tế, sự kiện, tin tức, tình huống thực tiễn sinh động giúp học sinh liên hệ kiến thức với thực tế.

2. QUY CHUẨN CÁC DẠNG CÂU HỎI (TYPE):
- "multiple_choice": Câu hỏi trắc nghiệm (gồm nội dung câu hỏi, 4 phương án lựa chọn A, B, C, D và chỉ có 1 đáp án đúng).
- "option": Câu hỏi lựa chọn (dạng Đúng/Sai, nối cột, hoặc chọn đáp án/thẻ từ phù hợp từ danh sách).
- "fill_in_blank": Câu hỏi điền vào chỗ trống (điền số, phép tính hoặc từ ngữ còn thiếu vào ô trống ...).
- "essay": Câu hỏi tự luận (bài toán có lời văn, trình bày chi tiết từng bước giải và kết luận đáp số).

3. TIÊU CHÍ ĐÁNH GIÁ (CRITERIA):
Đảm bảo mỗi câu hỏi được tạo ra đáp ứng đúng các tiêu chí tiêu chuẩn:
${typeof criteria === 'object' ? JSON.stringify(criteria, null, 2) : String(criteria)}

4. ĐỊNH DẠNG ĐẦU RA BẮT BUỘC (STRICT JSON OUTPUT):
BẮT BUỘC trả về duy nhất một đối tượng JSON với cấu trúc sau (KHÔNG kèm văn bản ngoài JSON, KHÔNG bọc trong khối \`\`\`json):
{
  "questions": [
    {
      "content": "Nội dung câu hỏi đầy đủ (string)",
      "level": "review_exercise | basic | normal | advance | discovery",
      "type": "multiple_choice | option | fill_in_blank | essay",
      "criteria": ["Tên tiêu chí 1", "Tên tiêu chí 2"],
      "answer": {
        // Cấu trúc đáp án phù hợp với từng dạng type
      },
      "explain": {
        "explanation": "Lời giải chi tiết và phương pháp giải giải thích rõ tại sao đáp án đúng (string hoặc object)"
      }
    }
  ]
}`;

// Build batch items for parallel execution via Batch API
const batchItems = [];
questions.forEach((q, idx) => {
  const count = q.number_of_questions || 1;
  const qPrompt = `YÊU CẦU TẠO ${count} CÂU HỎI TOÁN TIỂU HỌC:\n- Chủ đề/Tên bài: ${q.title}\n- Mức độ khó (level): ${q.level}\n- Dạng câu hỏi (type): ${q.type}\n- Số lượng câu cần tạo: ${count}\n\nTIÊU CHÍ BỔ SUNG (CRITERIA):\n${typeof criteria === 'object' ? JSON.stringify(criteria, null, 2) : String(criteria)}\n\nNGỮ CẢNH SGK THAM CHIẾU:\n${joinedContext || "Không có ngữ cảnh bổ sung."}\n\nBẮT BUỘC trả về JSON đối tượng {"questions": [ ... ]} chứa đúng ${count} câu hỏi. Mỗi câu BẮT BUỘC phải có đầy đủ các trường: "content", "level": "${q.level}", "type": "${q.type}", "criteria": [...], "answer": {...}, "explain": {"explanation": "..."}.`;

  batchItems.push({
    id: idx,
    prompt: qPrompt,
    system_instruction: systemInstruction
  });
});

if (batchItems.length === 0) {
  batchItems.push({
    id: 0,
    prompt: "Tạo 1 câu hỏi toán lớp 3 bám sát ngữ cảnh SGK.",
    system_instruction: systemInstruction
  });
}

return {
  batch_items: batchItems,
  user_id: userId,
  conversation_id: conversationId,
  criteria: criteria,
  questions: questions
};

const llmResult = $('LLM Call - Custom Exercise Generator').first().json || {};
const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || "";

const levelMap = {
  'theory_application': 'review_exercise',
  'review_exercise': 'review_exercise',
  'basic': 'basic',
  'medium': 'normal',
  'normal': 'normal',
  'advanced': 'advance',
  'advance': 'advance',
  'exploration': 'discovery',
  'discovery': 'discovery'
};

let requestedQuestions = [];
try {
  requestedQuestions = $('Security & Sanitization Gate').first().json.body.questions || [];
} catch (e) {
  requestedQuestions = [];
}

// Flatten expected question specs
let flatTargetSpecs = [];
requestedQuestions.forEach(q => {
  const count = q.number_of_questions || 1;
  for (let i = 0; i < count; i++) {
    flatTargetSpecs.push({
      title: q.title || "Bài tập toán",
      level: levelMap[String(q.level || "normal").trim().toLowerCase()] || String(q.level || "normal").trim().toLowerCase(),
      type: String(q.type || "multiple_choice").trim().toLowerCase()
    });
  }
});

let parsedQuestions = [];
let totalUsage = llmResult.aggregated_usage || llmResult.usage || {};

if (Array.isArray(llmResult.results)) {
  // Processing Batch API results
  llmResult.results.forEach((itemRes, batchIdx) => {
    const rawText = itemRes.text || "";
    const cleaned = rawText.replace(/```json/gi, "").replace(/```/gi, "").trim();
    let batchObj = null;
    try {
      batchObj = JSON.parse(cleaned);
    } catch(e) {
      const match = cleaned.match(/\{[\s\S]*\}/);
      if (match) {
        try { batchObj = JSON.parse(match[0]); } catch(e2) {}
      }
    }

    const targetSpec = requestedQuestions[batchIdx] || flatTargetSpecs[batchIdx] || { level: "normal", type: "multiple_choice" };
    const specLevel = levelMap[String(targetSpec.level || "normal").trim().toLowerCase()] || String(targetSpec.level || "normal").trim().toLowerCase();
    const specType = String(targetSpec.type || "multiple_choice").trim().toLowerCase();

    if (batchObj && Array.isArray(batchObj.questions)) {
      batchObj.questions.forEach((q, subIdx) => {
        const qRawLevel = String(q.level || specLevel).trim().toLowerCase();
        const qLevel = levelMap[qRawLevel] || qRawLevel || specLevel;
        const qType = String(q.type || specType).trim().toLowerCase();

        let criteriaList = [];
        if (Array.isArray(q.criteria)) criteriaList = q.criteria;
        else if (typeof q.criteria === 'string') criteriaList = [q.criteria];
        else if (typeof q.criteria === 'object' && q.criteria !== null) criteriaList = Object.values(q.criteria).map(String);

        parsedQuestions.push({
          content: String(q.content || q.question || q.prompt || q.cau_hoi || "").trim(),
          level: qLevel,
          type: qType,
          criteria: criteriaList,
          answer: typeof q.answer === 'object' && q.answer !== null ? q.answer : { result: String(q.answer || "") },
          explain: typeof q.explain === 'object' && q.explain !== null ? q.explain : { explanation: String(q.explain || "") }
        });
      });
    }
  });
} else {
  // Single output parsing fallback
  const rawText = llmResult.text || "";
  const cleaned = rawText.replace(/```json/gi, "").replace(/```/gi, "").trim();
  let outputObj = null;
  try {
    outputObj = JSON.parse(cleaned);
  } catch (e) {
    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { outputObj = JSON.parse(jsonMatch[0]); } catch (e2) {}
    }
  }

  if (outputObj && Array.isArray(outputObj.questions)) {
    outputObj.questions.forEach((q, idx) => {
      const fallbackSpec = flatTargetSpecs[idx] || flatTargetSpecs[0] || { level: "normal", type: "multiple_choice" };
      const rawLevel = String(q.level || fallbackSpec.level).trim().toLowerCase();
      const normalizedLevel = levelMap[rawLevel] || rawLevel || "normal";
      const qType = String(q.type || fallbackSpec.type).trim().toLowerCase();

      let criteriaList = [];
      if (Array.isArray(q.criteria)) criteriaList = q.criteria;
      else if (typeof q.criteria === 'string') criteriaList = [q.criteria];
      else if (typeof q.criteria === 'object' && q.criteria !== null) criteriaList = Object.values(q.criteria).map(String);

      parsedQuestions.push({
        content: String(q.content || q.question || q.prompt || q.cau_hoi || "").trim(),
        level: normalizedLevel,
        type: qType,
        criteria: criteriaList,
        answer: typeof q.answer === 'object' && q.answer !== null ? q.answer : { result: String(q.answer || "") },
        explain: typeof q.explain === 'object' && q.explain !== null ? q.explain : { explanation: String(q.explain || "") }
      });
    });
  }
}

if (parsedQuestions.length > 0) {
  return {
    status: "success",
    agent: "custom_exercise_generator",
    conversation_id: conversationId,
    questions: parsedQuestions,
    usage: totalUsage
  };
} else {
  return {
    status: "warning",
    agent: "custom_exercise_generator",
    conversation_id: conversationId,
    message: "Custom Exercise Generator output could not be parsed as valid JSON array.",
    raw_text: llmResult.text || "",
    questions: []
  };
}
